  9	import br.com.pousada.service.NotificationService;
 10	import br.com.pousada.service.ReportService;
 11	import br.com.pousada.service.ReservationService;
 12	import com.fasterxml.jackson.databind.ObjectMapper;
 13	import com.fasterxml.jackson.databind.SerializationFeature;
 14	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 15	import com.zaxxer.hikari.HikariConfig;
 16	import com.zaxxer.hikari.HikariDataSource;
 17	import io.javalin.Javalin;
 18	import io.javalin.http.Context;
 19	import io.javalin.json.JavalinJackson;
 20	
 21	import javax.sql.DataSource;
 22	
 23	public class Application {
 24	    public static void main(String[] args) {
 25	        DataSource dataSource = createDataSource();
 26	
 27	        RoomRepository roomRepository = new RoomRepository(dataSource);
 28	        MessageRepository messageRepository = new MessageRepository(dataSource);
 29	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 30	
 31	        DocumentService documentService = new DocumentService();
 32	        NotificationService notificationService = new NotificationService(messageRepository);
 33	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 34	        ReservationService reservationService = new ReservationService(
 35	            reservationRepository, roomRepository, documentService, notificationService);
 36	
 37	        RoomController roomController = new RoomController(roomRepository);
 38	        ReservationController reservationController = new ReservationController(reservationService);
 39	        MessageController messageController = new MessageController(messageRepository);
 40	        ReportController reportController = new ReportController(reportService);
 41	
 42	        int port = getPort();
 43	
 44	        ObjectMapper mapper = new ObjectMapper();
 45	        mapper.registerModule(new JavaTimeModule());
 46	        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 47	
 48	        Javalin app = Javalin.create(config -> {
 49	            config.jsonMapper(new JavalinJackson(mapper, true));
 50	        });
 51	
 52	        app.exception(InvalidRequestException.class, (e, ctx) ->
 53	            handleError(ctx, 400, "INVALID_REQUEST", e.getMessage()));
 54	
 55	        app.exception(RoomNotFoundException.class, (e, ctx) ->
 56	            handleError(ctx, 404, "ROOM_NOT_FOUND", e.getMessage()));
 57	
 58	        app.exception(ReservationNotFoundException.class, (e, ctx) ->
 59	            handleError(ctx, 404, "RESERVATION_NOT_FOUND", e.getMessage()));
 60	
 61	        app.exception(RoomUnavailableException.class, (e, ctx) ->
 62	            handleError(ctx, 409, "ROOM_UNAVAILABLE", e.getMessage()));
 63	
 64	        app.exception(OperationNotAllowedException.class, (e, ctx) ->
 65	            handleError(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage()));
 66	
 67	        app.exception(CapacityExceededException.class, (e, ctx) ->
 68	            handleError(ctx, 422, "CAPACITY_EXCEEDED", e.getMessage()));
 69	
 70	        app.exception(IllegalArgumentException.class, (e, ctx) ->
 71	            handleError(ctx, 400, "INVALID_REQUEST", e.getMessage()));
 72	
 73	        app.get("/rooms", roomController::getRooms);
 74	        app.post("/reservations", reservationController::createReservation);
 75	        app.get("/reservations/{id}", reservationController::getReservation);
 76	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 77	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 78	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 79	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 80	        app.get("/reservations/{id}/document", reservationController::getDocument);
 81	        app.get("/messages", messageController::getMessages);
 82	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 83	        app.get("/reports/revenue", reportController::getRevenueReport);
 84	
 85	        app.start(port);
 86	
 87	        System.out.println("Pousada Maré Alta system started on port " + port);
 88	    }
 89	
 90	    private static DataSource createDataSource() {
 91	        String url = System.getenv("DB_URL");
 92	        String user = System.getenv("DB_USER");
 93	        String password = System.getenv("DB_PASSWORD");
 94	
 95	        if (url == null || user == null || password == null) {
 96	            throw new RuntimeException("Database configuration missing. Set DB_URL, DB_USER, and DB_PASSWORD environment variables.");
 97	        }
 98	
 99	        HikariConfig config = new HikariConfig();
100	        config.setJdbcUrl(url);
101	        config.setUsername(user);
102	        config.setPassword(password);
103	        config.setMaximumPoolSize(10);
104	
105	        return new HikariDataSource(config);
106	    }
107	
108	    private static int getPort() {
109	        String portEnv = System.getenv("PORT");
110	        return portEnv != null ? Integer.parseInt(portEnv) : 7070;
111	    }
112	
113	    private static void handleError(Context ctx, int status, String error, String message) {
114	        ctx.status(status).json(new ErrorResponse(error, message));
115	    }
116	}
