246	import java.util.HashMap;
247	import java.util.Map;
248	
249	public class ReservationController {
250	    private final ReservationService reservationService;
251	
252	    public ReservationController(ReservationService reservationService) {
253	        this.reservationService = reservationService;
254	    }
255	
256	    public void createReservation(Context ctx) {
257	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
258	
259	        validateRequest(request);
260	
261	        GuestIdentification identification = parseIdentification(request);
262	        RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
263	
264	        Reservation reservation = reservationService.createReservation(
265	            request.roomNumber(),
266	            request.guestName(),
267	            request.guestEmail(),
268	            identification,
269	            request.checkIn(),
270	            request.checkOut(),
271	            request.guests(),
272	            ratePlan
273	        );
274	
275	        ctx.status(201).json(toReservationResponse(reservation));
276	    }
277	
278	    public void getReservation(Context ctx) {
279	        Long id = Long.parseLong(ctx.pathParam("id"));
280	        Reservation reservation = reservationService.getReservation(id);
281	        ctx.json(toReservationResponse(reservation));
282	    }
283	
284	    public void confirmReservation(Context ctx) {
285	        Long id = Long.parseLong(ctx.pathParam("id"));
286	        Reservation reservation = reservationService.confirmReservation(id);
287	        ctx.json(toReservationResponse(reservation));
288	    }
289	
290	    public void cancelReservation(Context ctx) {
291	        Long id = Long.parseLong(ctx.pathParam("id"));
292	        Reservation reservation = reservationService.cancelReservation(id);
293	        ctx.json(toReservationResponse(reservation));
294	    }
295	
296	    public void checkIn(Context ctx) {
297	        Long id = Long.parseLong(ctx.pathParam("id"));
298	        Reservation reservation = reservationService.checkIn(id);
299	        ctx.json(toReservationResponse(reservation));
300	    }
301	
302	    public void checkOut(Context ctx) {
303	        Long id = Long.parseLong(ctx.pathParam("id"));
304	        Document document = reservationService.checkOut(id);
305	        ctx.json(toDocumentResponse(document));
306	    }
307	
308	    public void getDocument(Context ctx) {
309	        Long id = Long.parseLong(ctx.pathParam("id"));
310	        Document document = reservationService.getDocument(id);
311	        ctx.json(toDocumentResponse(document));
312	    }
313	
314	    private void validateRequest(CreateReservationRequest request) {
315	        if (request.roomNumber() == null || request.guestName() == null ||
316	            request.guestEmail() == null || request.checkIn() == null ||
317	            request.checkOut() == null || request.guests() == null ||
318	            request.ratePlan() == null) {
319	            throw new InvalidRequestException("Missing required fields");
320	        }
321	
322	        int identificationCount = 0;
323	        if (request.guestCpf() != null) identificationCount++;
324	        if (request.companyCnpj() != null || request.companyName() != null) identificationCount++;
325	        if (request.guestPassport() != null || request.guestCountry() != null) identificationCount++;
326	
327	        if (identificationCount != 1) {
328	            throw new InvalidRequestException("Exactly one identification type is required");
329	        }
330	
331	        if (request.companyCnpj() != null && request.companyName() == null) {
332	            throw new InvalidRequestException("Company name is required with CNPJ");
333	        }
334	        if (request.companyName() != null && request.companyCnpj() == null) {
335	            throw new InvalidRequestException("CNPJ is required with company name");
336	        }
337	
338	        if (request.guestPassport() != null && request.guestCountry() == null) {
339	            throw new InvalidRequestException("Country is required with passport");
340	        }
341	        if (request.guestCountry() != null && request.guestPassport() == null) {
342	            throw new InvalidRequestException("Passport is required with country");
343	        }
344	    }
345	
346	    private GuestIdentification parseIdentification(CreateReservationRequest request) {
347	        if (request.guestCpf() != null) {
348	            return new CpfIdentification(request.guestCpf());
349	        } else if (request.companyCnpj() != null) {
350	            return new CnpjIdentification(request.companyCnpj(), request.companyName());
351	        } else {
352	            return new PassportIdentification(request.guestPassport(), request.guestCountry());
353	        }
354	    }
355	
356	    private Map<String, Object> toReservationResponse(Reservation reservation) {
357	        Map<String, Object> response = new HashMap<>();
358	        response.put("id", reservation.getId());
359	        response.put("roomNumber", reservation.getRoomNumber());
360	        response.put("guestName", reservation.getGuestName());
361	        response.put("guestEmail", reservation.getGuestEmail());
362	
363	        switch (reservation.getIdentification()) {
364	            case CpfIdentification cpf -> {
365	                response.put("guestCpf", cpf.cpf());
366	                response.put("companyCnpj", null);
367	                response.put("companyName", null);
368	                response.put("guestPassport", null);
369	                response.put("guestCountry", null);
370	            }
371	            case CnpjIdentification cnpj -> {
372	                response.put("guestCpf", null);
373	                response.put("companyCnpj", cnpj.cnpj());
374	                response.put("companyName", cnpj.companyName());
375	                response.put("guestPassport", null);
376	                response.put("guestCountry", null);
377	            }
378	            case PassportIdentification passport -> {
379	                response.put("guestCpf", null);
380	                response.put("companyCnpj", null);
381	                response.put("companyName", null);
382	                response.put("guestPassport", passport.passport());
383	                response.put("guestCountry", passport.country());
384	            }
385	        }
386	
387	        response.put("checkIn", reservation.getCheckIn());
388	        response.put("checkOut", reservation.getCheckOut());
389	        response.put("guests", reservation.getGuests());
390	        response.put("ratePlan", reservation.getRatePlan().name());
391	        response.put("nights", reservation.getNights());
392	        response.put("subtotal", reservation.getSubtotal());
393	        response.put("discount", reservation.getDiscount());
394	        response.put("total", reservation.getTotal());
395	        response.put("status", reservation.getStatus().name());
396	        response.put("amountPaid", reservation.getAmountPaid());
397	        response.put("refund", reservation.getRefund());
398	
399	        return response;
400	    }
401	
402	    private Map<String, Object> toDocumentResponse(Document document) {
403	        Map<String, Object> response = new HashMap<>();
404	        response.put("title", document.title());
405	        response.put("reservationId", document.reservationId());
406	        response.put("guestName", document.guestName());
407	        response.put("guestCpf", document.guestCpf());
408	        response.put("companyCnpj", document.companyCnpj());
409	        response.put("companyName", document.companyName());
410	        response.put("guestPassport", document.guestPassport());
411	        response.put("guestCountry", document.guestCountry());
412	        response.put("roomNumber", document.roomNumber());
413	        response.put("roomType", document.roomType());
414	        response.put("checkIn", document.checkIn());
415	        response.put("checkOut", document.checkOut());
416	        response.put("nights", document.nights());
417	        response.put("subtotal", document.subtotal());
418	        response.put("discount", document.discount());
419	        response.put("total", document.total());
420	        response.put("text", document.text());
421	        return response;
422	    }
423	}
