186	public class ReportController {
187	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
188	
189	    private final ReportService reportService;
190	
191	    public ReportController(ReportService reportService) {
192	        this.reportService = reportService;
193	    }
194	
195	    public void getOccupancyReport(Context ctx) {
196	        String dateParam = ctx.queryParam("date");
197	        if (dateParam == null) {
198	            throw new InvalidRequestException("Date parameter is required");
199	        }
200	
201	        LocalDate date;
202	        try {
203	            date = LocalDate.parse(dateParam, DATE_FORMAT);
204	        } catch (DateTimeParseException e) {
205	            throw new InvalidRequestException("Invalid date format. Expected: yyyy-MM-dd");
206	        }
207	
208	        String csv = reportService.generateOccupancyReport(date);
209	        ctx.contentType("text/csv; charset=utf-8").result(csv);
210	    }
211	
212	    public void getRevenueReport(Context ctx) {
213	        String monthParam = ctx.queryParam("month");
214	        if (monthParam == null) {
215	            throw new InvalidRequestException("Month parameter is required");
216	        }
217	
218	        String[] parts = monthParam.split("-");
219	        if (parts.length != 2) {
220	            throw new InvalidRequestException("Invalid month format. Expected: yyyy-MM");
221	        }
222	
223	        int year;
224	        int month;
225	        try {
226	            year = Integer.parseInt(parts[0]);
227	            month = Integer.parseInt(parts[1]);
228	            if (month < 1 || month > 12) {
229	                throw new InvalidRequestException("Month must be between 1 and 12");
230	            }
231	        } catch (NumberFormatException e) {
232	            throw new InvalidRequestException("Invalid month format. Expected: yyyy-MM");
233	        }
234	
235	        String csv = reportService.generateRevenueReport(year, month);
236	        ctx.contentType("text/csv; charset=utf-8").result(csv);
237	    }
