314	    private void validateRequest(CreateReservationRequest request) {
315	        if (request.roomNumber() == null || request.guestName() == null ||
316	            request.guestEmail() == null || request.checkIn() == null ||
317	            request.checkOut() == null || request.guests() == null ||
318	            request.ratePlan() == null) {
319	            throw new InvalidRequestException("Missing required fields");
320	        }
321	
322	        int identificationCount = 0;
323	        if (request.guestCpf() != null) identificationCount++;
324	        if (request.companyCnpj() != null || request.companyName() != null) identificationCount++;
325	        if (request.guestPassport() != null || request.guestCountry() != null) identificationCount++;
326	
327	        if (identificationCount != 1) {
328	            throw new InvalidRequestException("Exactly one identification type is required");
329	        }
330	
331	        if (request.companyCnpj() != null && request.companyName() == null) {
332	            throw new InvalidRequestException("Company name is required with CNPJ");
333	        }
334	        if (request.companyName() != null && request.companyCnpj() == null) {
335	            throw new InvalidRequestException("CNPJ is required with company name");
336	        }
337	
338	        if (request.guestPassport() != null && request.guestCountry() == null) {
339	            throw new InvalidRequestException("Country is required with passport");
340	        }
341	        if (request.guestCountry() != null && request.guestPassport() == null) {
342	            throw new InvalidRequestException("Passport is required with country");
343	        }
344	    }
345	
346	    private GuestIdentification parseIdentification(CreateReservationRequest request) {
347	        if (request.guestCpf() != null) {
348	            return new CpfIdentification(request.guestCpf());
349	        } else if (request.companyCnpj() != null) {
350	            return new CnpjIdentification(request.companyCnpj(), request.companyName());
351	        } else {
352	            return new PassportIdentification(request.guestPassport(), request.guestCountry());
353	        }
354	    }
