356	    private Map<String, Object> toReservationResponse(Reservation reservation) {
357	        Map<String, Object> response = new HashMap<>();
358	        response.put("id", reservation.getId());
359	        response.put("roomNumber", reservation.getRoomNumber());
360	        response.put("guestName", reservation.getGuestName());
361	        response.put("guestEmail", reservation.getGuestEmail());
362	
363	        switch (reservation.getIdentification()) {
364	            case CpfIdentification cpf -> {
365	                response.put("guestCpf", cpf.cpf());
366	                response.put("companyCnpj", null);
367	                response.put("companyName", null);
368	                response.put("guestPassport", null);
369	                response.put("guestCountry", null);
370	            }
371	            case CnpjIdentification cnpj -> {
372	                response.put("guestCpf", null);
373	                response.put("companyCnpj", cnpj.cnpj());
374	                response.put("companyName", cnpj.companyName());
375	                response.put("guestPassport", null);
376	                response.put("guestCountry", null);
377	            }
378	            case PassportIdentification passport -> {
379	                response.put("guestCpf", null);
380	                response.put("companyCnpj", null);
381	                response.put("companyName", null);
382	                response.put("guestPassport", passport.passport());
383	                response.put("guestCountry", passport.country());
384	            }
385	        }
386	
387	        response.put("checkIn", reservation.getCheckIn());
388	        response.put("checkOut", reservation.getCheckOut());
389	        response.put("guests", reservation.getGuests());
390	        response.put("ratePlan", reservation.getRatePlan().name());
391	        response.put("nights", reservation.getNights());
392	        response.put("subtotal", reservation.getSubtotal());
393	        response.put("discount", reservation.getDiscount());
394	        response.put("total", reservation.getTotal());
395	        response.put("status", reservation.getStatus().name());
396	        response.put("amountPaid", reservation.getAmountPaid());
397	        response.put("refund", reservation.getRefund());
398	
399	        return response;
400	    }
