138	    private String buildComprovante(Long id, String guestName, String cpf, String roomNumber,
139	                                   String roomType, java.time.LocalDate checkIn, java.time.LocalDate checkOut,
140	                                   int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
141	        StringBuilder sb = new StringBuilder();
142	        sb.append("Comprovante de reserva nº ").append(id).append("\n");
143	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(formatCpf(cpf)).append(")").append("\n");
144	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")").append("\n");
145	        sb.append("Entrada: ").append(checkIn.format(PT_DATE_FORMAT));
146	        sb.append(" | Saída: ").append(checkOut.format(PT_DATE_FORMAT));
147	        sb.append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append("\n");
148	        sb.append("Diárias: ").append(formatMoney(subtotal, PT_BR)).append("\n");
149	
150	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
151	            sb.append("Desconto: ").append(formatMoney(discount, PT_BR)).append("\n");
152	        }
153	
154	        sb.append("Total: ").append(formatMoney(total, PT_BR));
155	
156	        return sb.toString();
157	    }
