159	    private String buildFatura(Long id, String companyName, String cnpj, String guestName,
160	                              String roomNumber, String roomType, java.time.LocalDate checkIn,
161	                              java.time.LocalDate checkOut, int nights, BigDecimal subtotal,
162	                              BigDecimal discount, BigDecimal total, BigDecimal iss) {
163	        StringBuilder sb = new StringBuilder();
164	        sb.append("Fatura de hospedagem nº ").append(id).append("\n");
165	        sb.append("Empresa: ").append(companyName).append(" (CNPJ ").append(formatCnpj(cnpj)).append(")").append("\n");
166	        sb.append("Hóspede: ").append(guestName).append("\n");
167	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")").append("\n");
168	        sb.append("Entrada: ").append(checkIn.format(PT_DATE_FORMAT));
169	        sb.append(" | Saída: ").append(checkOut.format(PT_DATE_FORMAT));
170	        sb.append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append("\n");
171	        sb.append("Diárias: ").append(formatMoney(subtotal, PT_BR)).append("\n");
172	
173	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
174	            sb.append("Desconto: ").append(formatMoney(discount, PT_BR)).append("\n");
175	        }
176	
177	        sb.append("Total: ").append(formatMoney(total, PT_BR)).append("\n");
178	        sb.append("ISS retido (5%): ").append(formatMoney(iss, PT_BR));
179	
180	        return sb.toString();
181	    }
182	
183	    private String buildReceipt(Long id, String guestName, String passport, String country,
184	                               String roomNumber, String roomType, java.time.LocalDate checkIn,
185	                               java.time.LocalDate checkOut, int nights, BigDecimal subtotal,
186	                               BigDecimal discount, BigDecimal total) {
187	        StringBuilder sb = new StringBuilder();
188	        sb.append("Booking receipt no. ").append(id).append("\n");
189	        sb.append("Guest: ").append(guestName).append(" (passport ").append(passport)
190	          .append(", ").append(country).append(")").append("\n");
191	        sb.append("Room: ").append(roomNumber).append(" (").append(roomType).append(")").append("\n");
192	        sb.append("Check-in: ").append(checkIn.format(EN_DATE_FORMAT));
193	        sb.append(" | Check-out: ").append(checkOut.format(EN_DATE_FORMAT));
194	        sb.append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append("\n");
195	        sb.append("Nights: ").append(formatMoneyEn(subtotal)).append("\n");
196	
197	        if (discount.compareTo(BigDecimal.ZERO) > 0) {
198	            sb.append("Discount: ").append(formatMoneyEn(discount)).append("\n");
199	        }
200	
201	        sb.append("Total: ").append(formatMoneyEn(total));
202	
203	        return sb.toString();
204	    }
205	
206	    private String formatMoney(BigDecimal value, Locale locale) {
207	        NumberFormat formatter = NumberFormat.getCurrencyInstance(locale);
208	        return formatter.format(value);
209	    }
210	
211	    private String formatMoneyEn(BigDecimal value) {
212	        return String.format("BRL %,.2f", value);
213	    }
214	
215	    private String formatCpf(String cpf) {
216	        if (cpf.length() == 11) {
217	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
218	                   cpf.substring(6, 9) + "-" + cpf.substring(9, 11);
219	        }
220	        return cpf;
221	    }
222	
223	    private String formatCnpj(String cnpj) {
224	        if (cnpj.length() == 14) {
225	            return cnpj.substring(0, 2) + "." + cnpj.substring(2, 5) + "." +
226	                   cnpj.substring(5, 8) + "/" + cnpj.substring(8, 12) + "-" + cnpj.substring(12, 14);
227	        }
228	        return cnpj;
229	    }
