417	        Reservation reservation = getReservation(id);
418	
419	        if (!reservation.canConfirm()) {
420	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.getStatus());
421	        }
422	
423	        reservation.confirm();
424	        reservationRepository.save(reservation);
425	
426	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
427	        Document document = documentService.generateDocument(reservation, room);
428	        notificationService.sendConfirmationEmail(reservation.getGuestName(), reservation.getGuestEmail(), document);
