363	                            DocumentService documentService,
364	                            NotificationService notificationService) {
365	        this.reservationRepository = reservationRepository;
366	        this.roomRepository = roomRepository;
367	        this.documentService = documentService;
368	        this.notificationService = notificationService;
369	    }
370	
371	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
372	                                       GuestIdentification identification, LocalDate checkIn,
373	                                       LocalDate checkOut, int guests, RatePlan ratePlan) {
374	
375	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
376	            throw new InvalidRequestException("Check-out must be after check-in");
377	        }
378	
379	        if (guests < 1) {
380	            throw new InvalidRequestException("At least one guest is required");
381	        }
382	
383	        Room room = roomRepository.findByNumber(roomNumber)
384	            .orElseThrow(() -> new RoomNotFoundException(roomNumber));
385	
386	        if (guests > room.getCapacity()) {
387	            throw new CapacityExceededException(guests, room.getCapacity());
388	        }
389	
390	        List<Reservation> conflicts = reservationRepository.findActiveByRoomAndDateRange(
391	            roomNumber, checkIn, checkOut);
392	
393	        if (!conflicts.isEmpty()) {
394	            throw new RoomUnavailableException(roomNumber);
395	        }
396	
397	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
398	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room, checkIn, checkOut);
399	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
400	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
401	
402	        Reservation reservation = new Reservation(
403	            null, roomNumber, guestName, guestEmail, identification,
404	            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total,
405	            ReservationStatus.PENDING, BigDecimal.ZERO, null
406	        );
407	
408	        return reservationRepository.save(reservation);
409	    }
410	
411	    public Reservation getReservation(Long id) {
412	        return reservationRepository.findById(id)
413	            .orElseThrow(() -> new ReservationNotFoundException(id));
414	    }
415	
416	    public Reservation confirmReservation(Long id) {
417	        Reservation reservation = getReservation(id);
418	
419	        if (!reservation.canConfirm()) {
420	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.getStatus());
421	        }
422	
423	        reservation.confirm();
424	        reservationRepository.save(reservation);
425	
426	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
427	        Document document = documentService.generateDocument(reservation, room);
428	        notificationService.sendConfirmationEmail(reservation.getGuestName(), reservation.getGuestEmail(), document);
429	
430	        return reservation;
431	    }
432	
433	    public Reservation cancelReservation(Long id) {
434	        Reservation reservation = getReservation(id);
435	
436	        if (!reservation.canCancel()) {
437	            throw new OperationNotAllowedException("Cannot cancel reservation in status " + reservation.getStatus());
438	        }
439	
440	        reservation.cancel();
441	        return reservationRepository.save(reservation);
442	    }
443	
444	    public Reservation checkIn(Long id) {
445	        Reservation reservation = getReservation(id);
446	
447	        if (!reservation.canCheckIn()) {
448	            throw new OperationNotAllowedException("Cannot check-in reservation in status " + reservation.getStatus());
449	        }
450	
451	        reservation.checkIn();
452	        return reservationRepository.save(reservation);
453	    }
454	
455	    public Document checkOut(Long id) {
456	        Reservation reservation = getReservation(id);
457	
458	        if (!reservation.canCheckOut()) {
459	            throw new OperationNotAllowedException("Cannot check-out reservation in status " + reservation.getStatus());
460	        }
461	
462	        reservation.checkOut();
463	        reservationRepository.save(reservation);
464	
465	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
466	        return documentService.generateDocument(reservation, room);
467	    }
468	
469	    public Document getDocument(Long id) {
470	        Reservation reservation = getReservation(id);
471	
472	        if (!reservation.isPaid()) {
473	            throw new OperationNotAllowedException("Document only available for paid reservations");
474	        }
475	
476	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
477	        return documentService.generateDocument(reservation, room);
478	    }
479	}
