481	
482	import br.com.pousada.domain.RatePlan;
483	import br.com.pousada.domain.Room;
484	
485	import java.math.BigDecimal;
486	import java.math.RoundingMode;
487	import java.time.LocalDate;
488	
489	public class PriceCalculator {
490	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
491	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
492	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
493	
494	    public static BigDecimal calculateNightPrice(Room room, LocalDate night) {
495	        BigDecimal baseRate = room.getNightlyRate();
496	        if (SeasonUtil.isHighSeason(night)) {
497	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
498	        }
499	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
500	    }
501	
502	    public static BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
503	        BigDecimal subtotal = BigDecimal.ZERO;
504	        LocalDate current = checkIn;
505	
506	        while (current.isBefore(checkOut)) {
507	            BigDecimal nightPrice = calculateNightPrice(room, current);
508	            subtotal = subtotal.add(nightPrice);
509	            current = current.plusDays(1);
510	        }
511	
512	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
513	    }
514	
515	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
516	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
517	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT).setScale(2, RoundingMode.HALF_EVEN);
518	        }
519	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
520	    }
521	
522	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
523	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
524	    }
525	
526	    public static BigDecimal calculateISS(BigDecimal total) {
527	        return total.multiply(ISS_RATE).setScale(2, RoundingMode.HALF_EVEN);
528	    }
529	}
