532	import java.time.LocalDate;
533	
534	public class SeasonUtil {
535	    public static boolean isHighSeason(LocalDate date) {
536	        int month = date.getMonthValue();
537	        int day = date.getDayOfMonth();
538	
539	        // Julho inteiro
540	        if (month == 7) {
541	            return true;
542	        }
543	
544	        // 15 de dezembro até fim de fevereiro
545	        if (month == 12 && day >= 15) {
546	            return true;
547	        }
548	
549	        if (month == 1 || month == 2) {
550	            return true;
551	        }
552	
553	        return false;
554	    }
555	}

