  2	
  3	import br.com.pousada.domain.*;
  4	import br.com.pousada.service.DocumentService;
  5	import org.junit.jupiter.api.Test;
  6	
  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	
 10	import static org.junit.jupiter.api.Assertions.*;
 11	
 12	public class DocumentServiceTest {
 13	    private final DocumentService documentService = new DocumentService();
 14	
 15	    @Test
 16	    void testGenerateComprovanteWithCpf() {
 17	        Room room = new Room("201", RoomType.DELUXE);
 18	        Reservation reservation = new Reservation(
 19	            7L, "201", "Carla Dias", "carla@example.com",
 20	            new CpfIdentification("11122233344"),
 21	            LocalDate.of(2027, 3, 10),
 22	            LocalDate.of(2027, 3, 12),
 23	            2, RatePlan.STANDARD, 2,
 24	            new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"),
 25	            ReservationStatus.CONFIRMED, new BigDecimal("779.80"), null
 26	        );
 27	
 28	        Document document = documentService.generateDocument(reservation, room);
 29	
 30	        assertEquals("Comprovante de reserva", document.title());
 31	        assertEquals(7L, document.reservationId());
 32	        assertEquals("Carla Dias", document.guestName());
 33	        assertEquals("11122233344", document.guestCpf());
 34	        assertNull(document.companyCnpj());
 35	        assertNull(document.guestPassport());
 36	        assertTrue(document.text().contains("Comprovante de reserva nº 7"));
 37	        assertTrue(document.text().contains("Hóspede: Carla Dias (CPF 111.222.333-44)"));
 38	        assertTrue(document.text().contains("Quarto: 201 (DELUXE)"));
 39	        assertTrue(document.text().contains("2 diárias"));
 40	        assertTrue(document.text().contains("779,80"));
 41	    }
 42	
 43	    @Test
 44	    void testGenerateFaturaWithCnpj() {
 45	        Room room = new Room("201", RoomType.DELUXE);
 46	        Reservation reservation = new Reservation(
 47	            3L, "201", "Ana Souza", "ana@example.com",
 48	            new CnpjIdentification("12345678000190", "Tecnosul Ltda"),
 49	            LocalDate.of(2027, 3, 10),
 50	            LocalDate.of(2027, 3, 12),
 51	            2, RatePlan.STANDARD, 2,
 52	            new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"),
 53	            ReservationStatus.CONFIRMED, new BigDecimal("779.80"), null
 54	        );
 55	
 56	        Document document = documentService.generateDocument(reservation, room);
 57	
 58	        assertEquals("Fatura de hospedagem", document.title());
 59	        assertEquals("12345678000190", document.companyCnpj());
 60	        assertEquals("Tecnosul Ltda", document.companyName());
 61	        assertNull(document.guestCpf());
 62	        assertTrue(document.text().contains("Fatura de hospedagem nº 3"));
 63	        assertTrue(document.text().contains("Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)"));
 64	        assertTrue(document.text().contains("Hóspede: Ana Souza"));
 65	        assertTrue(document.text().contains("ISS retido (5%)"));
 66	        assertTrue(document.text().contains("38,99"));
 67	    }
 68	
 69	    @Test
 70	    void testGenerateReceiptWithPassport() {
 71	        Room room = new Room("201", RoomType.DELUXE);
 72	        Reservation reservation = new Reservation(
 73	            4L, "201", "John Smith", "john@example.com",
 74	            new PassportIdentification("X1234567", "United Kingdom"),
 75	            LocalDate.of(2027, 3, 10),
 76	            LocalDate.of(2027, 3, 12),
 77	            2, RatePlan.STANDARD, 2,
 78	            new BigDecimal("779.80"), BigDecimal.ZERO, new BigDecimal("779.80"),
 79	            ReservationStatus.CONFIRMED, new BigDecimal("779.80"), null
 80	        );
 81	
 82	        Document document = documentService.generateDocument(reservation, room);
 83	
 84	        assertEquals("Booking receipt", document.title());
 85	        assertEquals("X1234567", document.guestPassport());
 86	        assertEquals("United Kingdom", document.guestCountry());
 87	        assertNull(document.guestCpf());
 88	        assertNull(document.companyCnpj());
 89	        assertTrue(document.text().contains("Booking receipt no. 4"));
 90	        assertTrue(document.text().contains("Guest: John Smith (passport X1234567, United Kingdom)"));
 91	        assertTrue(document.text().contains("2 nights"));
 92	        assertTrue(document.text().contains("BRL 779.80"));
 93	        assertTrue(document.text().contains("Check-in: 2027-03-10"));
 94	    }
 95	
 96	    @Test
 97	    void testDocumentWithDiscount() {
 98	        Room room = new Room("101", RoomType.STANDARD);
 99	        Reservation reservation = new Reservation(
100	            5L, "101", "Maria Santos", "maria@example.com",
101	            new CpfIdentification("98765432100"),
102	            LocalDate.of(2027, 7, 10),
103	            LocalDate.of(2027, 7, 12),
104	            1, RatePlan.NON_REFUNDABLE, 2,
105	            new BigDecimal("599.76"), new BigDecimal("89.96"), new BigDecimal("509.80"),
106	            ReservationStatus.CONFIRMED, new BigDecimal("509.80"), null
107	        );
108	
109	        Document document = documentService.generateDocument(reservation, room);
110	
111	        assertTrue(document.text().contains("Diárias"));
112	        assertTrue(document.text().contains("599,76"));
113	        assertTrue(document.text().contains("Desconto"));
114	        assertTrue(document.text().contains("89,96"));
115	        assertTrue(document.text().contains("Total"));
116	        assertTrue(document.text().contains("509,80"));
117	    }
118	
119	    @Test
120	    void testDocumentSingleNight() {
121	        Room room = new Room("101", RoomType.STANDARD);
122	        Reservation reservation = new Reservation(
123	            6L, "101", "Pedro Lima", "pedro@example.com",
124	            new CpfIdentification("11111111111"),
125	            LocalDate.of(2027, 3, 10),
126	            LocalDate.of(2027, 3, 11),
127	            1, RatePlan.STANDARD, 1,
128	            new BigDecimal("249.90"), BigDecimal.ZERO, new BigDecimal("249.90"),
129	            ReservationStatus.CONFIRMED, new BigDecimal("249.90"), null
130	        );
131	
132	        Document document = documentService.generateDocument(reservation, room);
133	
134	        assertTrue(document.text().contains("1 diária"));
135	        assertFalse(document.text().contains("2 diárias"));
136	    }
137	}
